            # transpose and separate blocks

            dvals_list = [maybe_infer_to_datetimelike(row) for row in values]
            for n in range(len(dvals_list)):
                if isinstance(dvals_list[n], np.ndarray):
                    dvals_list[n] = dvals_list[n].reshape(1, -1)

            from pandas.core.internals.blocks import make_block

            # TODO: What about re-joining object columns?
            block_values = [
                make_block(dvals_list[n], placement=[n]) for n in range(len(dvals_list))
            ]

        else:
            datelike_vals = maybe_infer_to_datetimelike(values)
            block_values = [datelike_vals]
    else:
        block_values = [values]

    return create_block_manager_from_blocks(block_values, [columns, index])
```

```python
def init_ndarray(values, index, columns, dtype=None, copy=False):
    if isinstance(values, ABCSeries):
        if columns is None:
            if values.name is not None:
                columns = [values.name]
        if index is None:
            index = values.index
        else:
            values = values.reindex(index)

        if not len(values) and columns is not None and len(columns):
            values = np.empty((0, 1), dtype=object)

    if is_categorical_dtype(getattr(values, "dtype", None)) or is_categorical_dtype(dtype):
        if not hasattr(values, "dtype"):
            values = prep_ndarray(values, copy=copy)
            values = values.ravel()
        elif copy:
            values = values.copy()

        index, columns = _get_axes(len(values), 1, index, columns)
        return arrays_to_mgr([values], columns, index, columns, dtype=dtype)
    elif is_extension_array_dtype(values) or is_extension_array_dtype(dtype):
        if columns is None:
            columns = [0]
        return arrays_to_mgr([values], columns, index, columns, dtype=dtype)

    values = prep_ndarray(values, copy=copy)

    if dtype is not None:
        if not is_dtype_equal(values.dtype, dtype):
            try:
                if np.issubdtype(dtype, np.datetime64):
                    # Convert integer to datetime if dtype is datetime
                    epoch_time = pd.Timestamp('1970-01-01')
                    values = epoch_time + pd.to_timedelta(values.flatten(), unit='ns')
                    values = values.reshape(-1, values.shape[1]).astype(dtype)
                else:
                    values = values.astype(dtype)
            except Exception as orig:
                raise ValueError(f"failed to cast to '{dtype}' (Exception was: {orig})") from orig

    index, columns = _get_axes(*values.shape, index=index, columns=columns)
    values = values.T

    if dtype is None and is_object_dtype(values):
        if values.ndim == 2 and values.shape[0] != 1:
            dvals_list = [maybe_infer_to_datetimelike(row) for row in values]
            for n in range(len(dvals_list)):
                if isinstance(dvals_list[n], np.ndarray):
                    dvals_list[n] = dvals_list[n].reshape(1, -1)

            from pandas.core.internals.blocks import make_block
            block_values = [make_block(dvals_list[n], placement=[n]) for n in range(len(dvals_list))]

        else:
            datelike_vals = maybe_infer_to_datetimelike(values)
            block_values = [datelike_vals]
    else:
        block_values = [values]

    return create_block_manager_from_blocks(block_values, [columns, index])
